time`, `artist`, `description`) VALUES ('m-6', 'Thu', '19:00 - 21:15', 'วง Tewly', 'Smooth acoustic pop & rock.');\nINSERT INTO `music` (`music_id`, `show_day`, `show_time`, `artist`, `description`) VALUES ('m-7', 'Thu', '21:30 - 22:30', 'วง Chilling Groove', 'Funky grooves and soul.');\nINSERT INTO `music` (`music_id`, `show_day`, `show_time`, `artist`, `description`) VALUES ('m-8', 'Fri', '18:45 - 20:45', 'วง Tewly', 'Popular hit songs and request sets.');\nINSERT INTO `music` (`music_id`, `show_day`, `show_time`, `artist`, `description`) VALUES ('m-9', 'Fri', '21:00 - 22:00', 'วง Karuna', 'Grunge and alternative rock.');\nINSERT INTO `music` (`music_id`, `show_day`, `show_time`, `artist`, `description`) VALUES ('music_6a9aa53928dd2', 'Wed', '22:15 - 23:15', 'วง Tewly', '80s-90s');\nINSERT INTO `music` (`music_id`, `show_day`, `show_time`, `artist`, `description`) VALUES ('music_6aa12dc4e6c35', 'Thu', '22:45 - 23:45', 'วง Black Devil', 'pop. 80 rock 70');\n\nDROP TABLE IF EXISTS `promotion`;\nCREATE TABLE `promotion` (
  `promo_id` varchar(50) NOT NULL,
  `promo_title` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `offer` varchar(255) NOT NULL,
  `promo_period` varchar(255) NOT NULL,
  `image_path` varchar(255) NOT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`promo_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nINSERT INTO `promotion` (`promo_id`, `promo_title`, `description`, `offer`, `promo_period`, `image_path`, `is_active`) VALUES ('promo_6a98354bc5a10', '3 สาว ก่อน 3 ทุ่ม ฟรี 1 เหยือก', 'สาว ๆ มา 3 คน ก่อน 21:00 น. รับฟรี ตะวันแดง 1 Pitcher! (มูลค่า 399.-) เฉพาะวันจันทร์และอังคารเท่านั้น! คราฟต์เบียร์เย็นๆ บรรยากาศดี ดนตรีเพราะ... จะรออะไร!', '', 'ทุกวันจันทร์และอังคาร ก่อนเวลา 21:00 น.', 'images/promotions/uploaded_1788360011_791383960_122283290132129427_324725330320101261_n.jpg', '1');\nINSERT INTO `promotion` (`promo_id`, `promo_title`, `description`, `offer`, `promo_period`, `image_path`, `is_active`) VALUES ('promo_6a9835f77c650', 'เดือนนี้เดือนเกิด... ต้องจัดที่ CHIT HOLE! 🎂🍻', 'วันเกิดปีนี้ พาเพื่อนมาเลี้ยงฉลองกันให้เต็มที่! รับส่วนลดค่าอาหาร 10% ทันที เมื่อมาฉลองวันเกิดที่ CHIT HOLE เชียงใหม่ สันทราย 📍 เฉพาะสาขา CHIT HOLE เชียงใหม่ สันทราย 🎁 สิทธิพิเศษ: ลดค่าอาหาร 10% 📝 แสดงบัตรประชาชนก่อนใช้สิทธิ', '', 'ตลอดเดือนเกิด', 'images/promotions/uploaded_1788360183_756444299_122279188670129427_5185743561094400021_n.jpg', '1');\nINSERT INTO `promotion` (`promo_id`, `promo_title`, `description`, `offer`, `promo_period`, `image_path`, `is_active`) VALUES ('promo_6aa12cd375577', 'PROMOTION HAPPY HOUR (ลดราคาตะวันแดง)', 'คำอธิบายเงื่อนไข\r\n\r\nรายการราคาพิเศษช่วง Happy Hour:\r\n\r\nแก้วเล็ก (350 ML): 99 บาท (จากปกติ 149 บาท)\r\n\r\nเหยือก (1000 ML): 289 บาท (จากปกติ 399 บาท)\r\n\r\nทาวเวอร์ (3000 ML): 859 บาท (จากปกติ 999 บาท)\r\n\r\nสิทธิ์นี้ใช้ได้เฉพาะช่วงเวลา HAPPY HOUR 17:00 – 21:00 น. เท่านั้น\r\n\r\nไม่สามารถใช้ร่วมกับโปรโมชันอื่นได้', '', '17:00 – 21:00 น.', 'images/promotions/uploaded_1788947667_IMG_0181.JPG', '1');\nINSERT INTO `promotion` (`promo_id`, `promo_title`, `description`, `offer`, `promo_period`, `image_path`, `is_active`) VALUES ('promo_beerflight500', 'Beer Flight เซ็ต 4 แก้ว ชิมครบจบในคืนเดียว เพียง 500.-', 'ลิ้มลองมิติความอร่อยของคราฟต์เบียร์แบบหลากหลาย! จัดเซ็ตทดลองชิม 4 สไตล์ 4 แก้วในถาดไม้เลิศหรู ให้คุณค้นหารสชาติโปรดในราคาสุดพิเศษเพียง 500 บาท', '', 'ทุกวัน 17:00 - 24:00 น.', 'images/promotions/uploaded_1785354569_729349129_122276006246129427_6361504741932678356_n__2_.jpg', '1');\nINSERT INTO `promotion` (`promo_id`, `promo_title`, `description`, `offer`, `promo_period`, `image_path`, `is_active`) VALUES ('promo_bitcoin10off', 'จ่ายด้วยบิตคอยน์ (Bitcoin) ลดทันที 10%', 'สายคริปโทห้ามพลาด! CHIT HOLE เปิดรับชำระค่าอาหารและเครื่องดื่มด้วย Bitcoin (BTC) ผ่าน Lightning Network รับส่วนลดพิเศษ 10% ทันทีทุกบิล', '', 'เปิดรับชำระทุกวัน ทุกช่วงเวลา', 'images/promotions/uploaded_1785617048________________1-3__1_.jpg', '1');\nINSERT INTO `promotion` (`promo_id`, `promo_title`, `description`, `offer`, `promo_period`, `image_path`, `is_active`) VALUES ('promo_onesongonebeer', 'ONE SONG, ONE BEER ร้องแลกแก้ว ดีก็รับ เพี้ยนก็แจก', 'เปิดเวทีให้สายร้อง! ขึ้นมาร้องเพลงโปรด 1 เพลง รับเบียร์สดฟรีทันที 1 แก้ว ร้องดีเสียงทรงพลังเราแจก ร้องเพี้ยนฮากระจายเรายิ่งแจก! มาร่วมสนุกสร้างความบันเทิงด้วยกันที่ CHIT HOLE', '', 'ทุกคืนวันศุกร์และเสาร์ 20:00 - 23:00 น.', 'images/promotions/751026922_122278510508129427_3687616286560289044_n.jpg', '1');\n\nDROP TABLE IF EXISTS `reservation`;\nCREATE TABLE `reservation` (
  `reservation_id` varchar(50) NOT NULL,
  `customer_name` varchar(255) NOT NULL,
  `customer_phone` varchar(50) NOT NULL,
  `reservation_date` varchar(20) NOT NULL,
  `reservation_time` varchar(20) NOT NULL,
  `guest_count` int(11) NOT NULL,
  `table_id` varchar(50) DEFAULT NULL,
  `reservation_status` varchar(50) DEFAULT 'PENDING',
  `cancel_reason` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`reservation_id`),
  KEY `table_id` (`table_id`),
  CONSTRAINT `reservation_ibfk_1` FOREIGN KEY (`table_id`) REFERENCES `table` (`table_id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nINSERT INTO `reservation` (`reservation_id`, `customer_name`, `customer_phone`, `reservation_date`, `reservation_time`, `guest_count`, `table_id`, `reservation_status`, `cancel_reason`, `created_at`, `updated_at`) VALUES ('CHITHOLECNX_6a95d203845f1', 'นุ๊ก', '0800711996', '2026-09-01', '19:00', '2', 'd-1', 'CANCELLED', 'โค๊ะมีลูกค้าใช้งาน', '2026-09-01 02:12:03', '2026-09-01 23:07:38');\nINSERT INTO `reservation` (`reservation_id`, `customer_name`, `customer_phone`, `reservation_date`, `reservation_time`, `guest_count`, `table_id`, `reservation_status`, `cancel_reason`, `created_at`, `updated_at`) VALUES ('CHITHOLECNX_6a95da1d0148b', 'joy', '0800711996', '2026-09-01', '19:00', '2', 'd-1', 'CANCELLED', 'โต๊ะเต็ม', '2026-09-01 02:46:37', '2026-09-01 23:07:24');\nINSERT INTO `reservation` (`reservation_id`, `customer_name`, `customer_phone`, `reservation_date`, `reservation_time`, `guest_count`, `table_id`, `reservation_status`, `cancel_reason`, `created_at`, `updated_at`) VALUES ('CHITHOLECNX_6a96f8efe1e17', 'นุ๊ก', '0800711996', '2026-09-01', '19:00', '2', 'd-2', 'COMPLETED', NULL, '2026-09-01 23:10:23', '2026-09-02 01:54:31');\nINSERT INTO `reservation` (`reservation_id`, `customer_name`, `customer_phone`, `reservation_date`, `reservation_time`, `guest_count`, `table_id`, `reservation_status`, `cancel_reason`, `created_at`, `updated_at`) VALUES ('CHITHOLECNX_6a971ce8d6b50', 'เจม', '0800711996', '2026-09-01', '19:00', '2', 'd-1', 'COMPLETED', NULL, '2026-09-02 01:43:52', '2026-09-02 01:54:29');\nINSERT INTO `reservation` (`reservation_id`, `customer_name`, `customer_phone`, `reservation_date`, `reservation_time`, `guest_count`, `table_id`, `reservation_status`, `cancel_reason`, `created_at`, `updated_at`) VALUES ('CHITHOLECNX_6a971d0e57cb4', 'เจม', '0800711996', '2026-09-02', '19:00', '2', 's-14', 'COMPLETED', NULL, '2026-09-02 01:44:30', '2026-09-02 01:49:53');\nINSERT INTO `reservation` (`reserv